    /// <summary>
    /// The Amazon ECS settings for the compute environment. These settings control CloudWatch Container Insights collection for the compute environment. containerInsights -&gt; (string) Specifies the CloudWatch Container Insights mode for the compute environment. Valid values are: ENABLED Turns on standard Container Insights, which collects CPU, memory, disk, and network utilization metrics for the compute environment. ENHANCED Turns on enhanced Container Insights, which collects the standard metrics along with additional per-task observability metrics. DISABLED Turns off Container Insights for the compute environment. If you don't specify a value, the default is DISABLED . For more information, see Container Insights in the Batch User Guide . Possible values: • ENABLED • ENHANCED • DISABLED Shorthand Syntax: containerInsights=string JSON Syntax: { "containerInsights": "ENABLED"|"ENHANCED"|"DISABLED" }
    /// </summary>
    [CliOption("--ecs-settings")]
    public string? EcsSettings { get; set; }

